"""A G-code file's metadata from its own comments, for the fields
Moonraker's metadata lacks: an older Moonraker (the Creality Hi's, 2022)
doesn't know the Orca family of slicers (OrcaSlicer, Creality Print,
Snapmaker Orca, Bambu Studio) and gives "slicer: Unknown" with no
estimated time, layer count or filament. Those slicers write them as
comments in the header and in the block before the config at the end:

  ; generated by Creality_Print V7.2.0.5225 on 2026-08-03 at 20:15:08
  ; total layer number: 22
  ; max_z_height: 4.64
  ...
  ; filament used [mm] = 3583.01, 0.00     (per filament)
  ; filament used [g] = 10.69, 0.00
  ; total filament used [g] = 10.69
  ; total layers count = 240
  ; estimated printing time (normal mode) = 1h 25m 13s
  ; filament_type = PLA;PETG

merged() fills only what Moonraker's metadata doesn't have, never
overrides it. Blocking: reads the file's first and last few hundred KB.
"""

from __future__ import annotations
import os
import re
from typing import Any, Dict, List, Optional

HEAD_BYTES = 64 * 1024
TAIL_BYTES = 512 * 1024
RX_GENERATED = re.compile(
    r";\s*generated by\s+(.+?)(?:\s+on\s+\d{4}-\d\d-\d\d.*)?$", re.I)
RX_DURATION = re.compile(r"(?:(\d+)d)?\s*(?:(\d+)h)?\s*(?:(\d+)m)?\s*"
                         r"(?:(\d+)s)?")


def duration(text: str) -> Optional[float]:
    """"1h 25m 13s", "41m 1s", "2d 3h 4m 5s" → seconds."""
    m = RX_DURATION.fullmatch(text.strip())
    if not m or not any(m.groups()):
        return None
    d, h, mi, s = (int(x or 0) for x in m.groups())
    return float(((d * 24 + h) * 60 + mi) * 60 + s)


def numbers(text: str) -> List[float]:
    out = []
    for part in re.split(r"[,;]", text):
        try:
            out.append(float(part.strip()))
        except ValueError:
            pass
    return out


def _comments(chunk: bytes) -> Dict[str, str]:
    """"; key = value" and "; key: value" comments, first one wins."""
    out: Dict[str, str] = {}
    for raw in chunk.splitlines():
        if not raw.startswith(b";") or len(raw) > 2000:
            continue
        line = raw.decode("utf-8", "replace").lstrip("; \t").rstrip()
        m = RX_GENERATED.match("; " + line)
        if m and "generated" not in out:
            out["generated"] = m.group(1).strip()
            continue
        key, sep, value = line.partition(" = ")
        if not sep:
            key, sep, value = line.partition(": ")
        if sep and key and key not in out:
            out[key.strip().lower()] = value.strip()
    return out


def from_file(path: str) -> Dict[str, Any]:
    """Moonraker-style metadata fields from the file's comments (only the
    ones found)."""
    try:
        size = os.path.getsize(path)
        with open(path, "rb") as f:
            head = f.read(HEAD_BYTES)
            f.seek(max(0, size - TAIL_BYTES))
            tail = f.read(TAIL_BYTES)
    except OSError:
        return {}
    c = _comments(tail)
    for k, v in _comments(head).items():
        c.setdefault(k, v)     # the end block wins (it is the slicer's sum)
    out: Dict[str, Any] = {}
    gen = c.get("generated")
    if gen:
        # "Snapmaker Orca 2.3.5", "Creality_Print V7.2.0.5225"
        m = re.fullmatch(r"(.+?)\s+[Vv]?(\d[\w.+-]*)", gen)
        name, version = (m.group(1), m.group(2)) if m else (gen, "")
        out["slicer"] = name.replace("_", " ").strip()
        if version:
            out["slicer_version"] = version
    est = c.get("estimated printing time (normal mode)") or \
        c.get("estimated printing time")
    secs = duration(est) if est else None
    if secs:
        out["estimated_time"] = secs
    # The header's layer number counts the layers printed; the end
    # block's count can include one more (Creality Print: 22 vs 23)
    for key in ("total layer number", "total layers count"):
        n = numbers(c.get(key, ""))
        if n and n[0] > 0:
            out["layer_count"] = int(n[0])
            break
    mm = numbers(c.get("filament used [mm]", ""))
    if mm and sum(mm) > 0:
        out["filament_total"] = round(sum(mm), 2)
    grams = numbers(c.get("filament used [g]", ""))
    if grams and sum(grams) > 0:
        out["filament_weight"] = grams
    total_g = numbers(c.get("total filament used [g]", ""))
    if total_g and total_g[0] > 0:
        out["filament_weight_total"] = total_g[0]
    elif grams and sum(grams) > 0:
        out["filament_weight_total"] = round(sum(grams), 2)
    if c.get("filament_type"):
        out["filament_type"] = c["filament_type"]
    z = numbers(c.get("max_z_height", ""))
    if z and z[0] > 0:
        out["object_height"] = z[0]
    return out


def merged(moonraker: Dict[str, Any], own: Dict[str, Any]
           ) -> Dict[str, Any]:
    """Moonraker's metadata with the file's own values where it has none
    (missing, empty or "Unknown"); Moonraker's are never replaced."""
    out = dict(moonraker or {})
    for key, value in own.items():
        have = out.get(key)
        if have in (None, "", [], 0) or (key == "slicer"
                                         and have == "Unknown"):
            out[key] = value
    return out
